/* Education: Section heading */
section[id="education"] > section-heading {
	color: #000000;
}

/* Education: Item container */
section[id="education"] > section-items > item {
	color: #000000;
}

/* Education: Primary text */
section[id="education"] field:not([name="content"]):not([name="description"]):not([name="recipient"]):not([name="keywords"]) {
	color: #000000;
}

/* Education: Primary text */
section[id="education"] field:not([name="content"]):not([name="description"]):not([name="recipient"]):not([name="keywords"]):not([role~="primary-text"]),
section[id="education"] item[role~="nested-role"] > item-header > field[name="position"] {
	font-weight: 600;
}

/* Education: Primary text: combined text host */
section[id="education"] combined-text {
	color: #000000;
	font-weight: 600;
}

/* Education: Primary text: Scizor Bold final color */
resume[template="scizor"] section[id="education"] field:not([name="content"]):not([name="description"]):not([name="recipient"]):not([name="keywords"])[role~="primary-text"][name="company"],
resume[template="scizor"] section[id="education"] field:not([name="content"]):not([name="description"]):not([name="recipient"]):not([name="keywords"])[role~="primary-text"][name="school"],
