resume[template="scizor"] section[id="education"] field:not([name="content"]):not([name="description"]):not([name="recipient"]):not([name="keywords"])[role~="primary-text"][name="title"] {
	color: #000000;
}

/* Legacy Bold hosts keep the template bold weight; award titles remain the explicit unbold exception. */

/* Education: Secondary text */
section[id="education"] field[name="keywords"] {
	color: #000000;
}

/* Education: Paragraph */
section[id="education"] rich-text paragraph {
	color: #000000;
}

/* Education: List */
section[id="education"] rich-text list {
	color: #000000;
}

/* Education: Link */
section[id="education"] item > link,
section[id="education"] item > template-part > link,
section[id="education"] item-header > link,
section[id="education"] item-header > template-part > link {
	color: #000000;
}

/* Education: Level indicator */
section[id="education"] level {
	color: #000000;
}
